#include <glm/glm.hpp>

struct Particle
{
    glm::vec3 position, velocity, acceleration, force;
    float density;
};

glm::vec3 calculateViscosityForce(Particle* pi, Particle* pj, float mass, float viscosity, float spikyLap, float h)
{
    glm::vec3 r_ji = pj->position - pi->position;
    float r = glm::length(r_ji);

    if (r >= h || r == 0.0f) {
        return glm::vec3(0.0f);
    }

    glm::vec3 v_ji = pj->velocity - pi->velocity;
    float kernel = spikyLap * (h - r) / (h * h * h);

    return mass * mass * viscosity * v_ji * kernel;
}

